$ErrorActionPreference='Stop'
$root=Split-Path -Parent $PSScriptRoot;$matrix=Get-Content -Raw (Join-Path $root 'baseline\game004_asset_matrix.json') -Encoding UTF8|ConvertFrom-Json;$out=Join-Path $root 'handoff\asset_production_v001\batches';New-Item -ItemType Directory -Force $out|Out-Null
$prefix='GAME-004 approved art direction: warm ivory and sage-green habitat pod, rounded toy-like 3D animated-film render, soft diffuse lighting, gentle child-friendly forms, portrait mobile training-game composition, clear semantic silhouette, no text, no pseudo-UI, no watermark, no scary or sharp harmful details.'
$groups=@{L1=@();L2=@();L3=@();L4=@();L5=@()}
foreach($op in $matrix.opportunities){$groups[[string]$op.l_level]+=[ordered]@{game_pack_id=$op.game_pack_id;opportunity_id=$op.opportunity_id;frozen_content=$op.frozen_content;prompt=$prefix+' Create a clean isolated runtime asset set for this frozen opportunity: '+$op.frozen_content+' Separate target, distractor, region marker and natural outcome concepts; no text.'}}
foreach($level in $groups.Keys){$batch=[ordered]@{schema_version='game004-image-batch-spec-v1';baseline_version='GAME004-BASELINE-V1';level=$level;asset_policy='candidate_only_until_visual_review';items=$groups[$level]};$batch|ConvertTo-Json -Depth 10|Set-Content (Join-Path $out ('GAME004_'+$level+'_IMAGE_BATCH_SPEC_V1.json')) -Encoding UTF8}
@('# GAME-004 IMAGE PRODUCTION RULES V1','','Recommended models: Seedream v5 Pro for style masters; Seedream v5 Lite Sequential for related variants; Nano Banana Pro or Seedream Edit for reference-consistent edits. Do not auto-submit API tasks until batch review.','','Immutable rules:','- Do not change frozen_content.','- Do not use a full-screen image as a runtime hit area.','- Target, distractor, region, and outcome must be split and have asset_id.','- Each candidate records source, model, prediction_id, and rights_status.','- L5 photos require authorization or remain inactive.','- candidate/processed is not approved.')|Set-Content (Join-Path $out 'GAME004_IMAGE_PRODUCTION_RULES_V1.md') -Encoding UTF8
Write-Host 'ASSET_BATCH_SPEC_BUILD_PASS L1=24 L2=24 L3=24 L4=24 L5=24'
